// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuardTransient.sol";

interface ILaunchpadCreatorV3 { function creatorOf(address token) external view returns (address); }

/**
 * @title ElcasLaunchTokenV3 — a fixed-supply ERC-20 made by the EL launchpad (1e9, 18 decimals, no mint, no tax, no
 * blacklist, no owner) carrying its own on-chain profile, plus HOLDER REWARDS:
 *
 *  If the creator chose it at launch, the creator's share of the trading fee is turned into a Ledger-approved RWA
 *  index (up to 5 assets) and paid to holders pro rata. Accounting is the classic "magnified reward per share":
 *  distribute() raises a per-share counter, every balance change books a correction, holders claim() whenever they like
 *  — no loop over holders, constant gas per transfer. Pools (the Uniswap v4 PoolManager), the launchpad, its reserve,
 *  the hook, product contracts (casino rooms / books) and the dead address earn nothing: their share stays with real
 *  holders. Snipe protection lives in the launch hook (buys go through the launchpad's router during the window).
 */
contract ElcasLaunchTokenV3 is ERC20, ReentrancyGuardTransient {
    using SafeERC20 for IERC20;

    uint256 public constant SUPPLY = 1_000_000_000 ether;
    uint256 public constant MAX_REWARD_ASSETS = 5;
    uint256 internal constant MAG = 2 ** 128;

    struct Socials { string website; string x; string telegram; string discord; string farcaster; }

    address public immutable launchpad;
    string  public logo;
    string  public description;
    Socials internal _socials;

    // ── holder rewards ──────────────────────────────────────────────────────────────────────────────────────────────
    address[] public rewardAssets;                                   // fixed once by the launchpad (empty = none)
    mapping(address => bool) public excluded;                         // earns no rewards
    uint256 public excludedSupply;                                    // tokens held by excluded addresses
    mapping(address => uint256) public perShare;                      // reward asset → magnified reward per token
    mapping(address => mapping(address => int256)) internal _corr;    // reward asset → holder → correction
    mapping(address => mapping(address => uint256)) public claimed;   // reward asset → holder → paid out

    event MetadataUpdated(string logo, string description);
    event SocialsUpdated(string website, string x, string telegram, string discord, string farcaster);
    event Excluded(address indexed who, bool on);
    event RewardsDistributed(address indexed asset, uint256 amount);
    event RewardClaimed(address indexed holder, address indexed asset, uint256 amount);

    error NotCreator(); error NotLaunchpad(); error BadParam(); error NothingToReward();

    /// made by the launchpad's parts contract (ElcasLaunchPartsV3) on the launchpad's behalf: the launchpad gets the supply
    constructor(address launchpad_, string memory name_, string memory symbol_, string memory logo_, string memory description_, Socials memory s)
        ERC20(name_, symbol_)
    {
        launchpad = launchpad_;
        logo = logo_; description = description_; _socials = s;
        excluded[launchpad_] = true;                                  // the launchpad (minted below, excluded first)
        emit Excluded(launchpad_, true);
        _mint(launchpad_, SUPPLY);
    }

    // ═════════════════════════════════════ profile ═══════════════════════════
    function creator() public view returns (address) { return ILaunchpadCreatorV3(launchpad).creatorOf(address(this)); }
    function socials() external view returns (string memory website, string memory x, string memory telegram, string memory discord, string memory farcaster) {
        Socials storage s = _socials;
        return (s.website, s.x, s.telegram, s.discord, s.farcaster);
    }
    function setMetadata(string calldata logo_, string calldata description_) external {
        if (msg.sender != creator()) revert NotCreator();
        logo = logo_; description = description_;
        emit MetadataUpdated(logo_, description_);
    }
    function setSocials(Socials calldata s) external {
        if (msg.sender != creator()) revert NotCreator();
        _socials = s;
        emit SocialsUpdated(s.website, s.x, s.telegram, s.discord, s.farcaster);
    }

    // ═════════════════════════════════════ launchpad ═════════════════════════
    /** once, at launch: the index the creator picked (empty = the creator keeps their share; no holder rewards) */
    function setRewardAssets(address[] calldata assets) external {
        if (msg.sender != launchpad || rewardAssets.length != 0) revert NotLaunchpad();
        if (assets.length > MAX_REWARD_ASSETS) revert BadParam();
        for (uint256 i; i < assets.length; i++) { if (assets[i] == address(0) || assets[i] == address(this)) revert BadParam(); rewardAssets.push(assets[i]); }
    }

    /** the launchpad marks pools / its reserve / the hook / product contracts as non-earning (their share goes to holders) */
    function setExcluded(address who, bool on) external {
        if (msg.sender != launchpad) revert NotLaunchpad();
        if (excluded[who] == on) return;
        uint256 bal = balanceOf(who);
        // leaving / joining the earning set: book the balance at today's counters so nothing is gained or lost
        for (uint256 i; i < rewardAssets.length; i++) {
            address a = rewardAssets[i];
            if (on) _corr[a][who] += int256(perShare[a] * bal);       // freeze what it earned so far…
            else _corr[a][who] -= int256(perShare[a] * bal);          // …and start from today's counter
        }
        if (on) excludedSupply += bal; else excludedSupply -= bal;
        excluded[who] = on;
        emit Excluded(who, on);
    }

    // ═════════════════════════════════════ rewards ═══════════════════════════
    /** anyone: pay `amount` of a reward asset to every earning holder (pulled from the caller) */
    function distribute(address asset, uint256 amount) external nonReentrant {
        if (!_isReward(asset)) revert BadParam();
        uint256 eligible = totalSupply() - excludedSupply;
        if (eligible == 0 || amount == 0) revert NothingToReward();
        uint256 before = IERC20(asset).balanceOf(address(this));
        IERC20(asset).safeTransferFrom(msg.sender, address(this), amount);
        uint256 got = IERC20(asset).balanceOf(address(this)) - before;
        perShare[asset] += got * MAG / eligible;
        emit RewardsDistributed(asset, got);
    }

    function claimable(address asset, address holder) public view returns (uint256) {
        if (excluded[holder]) {
            // an excluded address keeps only what it had earned before it was excluded (its frozen correction)
            int256 frozen = _corr[asset][holder];
            uint256 c = frozen > 0 ? uint256(frozen) / MAG : 0;
            return c > claimed[asset][holder] ? c - claimed[asset][holder] : 0;
        }
        int256 acc = int256(perShare[asset] * balanceOf(holder)) + _corr[asset][holder];
        uint256 total = acc > 0 ? uint256(acc) / MAG : 0;
        return total > claimed[asset][holder] ? total - claimed[asset][holder] : 0;
    }

    /** claim every reward asset to `to` */
    function claim(address to) external nonReentrant {
        if (to == address(0)) revert BadParam();
        for (uint256 i; i < rewardAssets.length; i++) {
            address a = rewardAssets[i];
            uint256 c = claimable(a, msg.sender);
            if (c == 0) continue;
            claimed[a][msg.sender] += c;
            IERC20(a).safeTransfer(to, c);
            emit RewardClaimed(msg.sender, a, c);
        }
    }

    function rewardAssetsList() external view returns (address[] memory) { return rewardAssets; }
    function _isReward(address a) internal view returns (bool) { for (uint256 i; i < rewardAssets.length; i++) if (rewardAssets[i] == a) return true; return false; }

    function _update(address from, address to, uint256 value) internal override {
        super._update(from, to, value);
        bool exFrom = from == address(0) || excluded[from];
        bool exTo = to == address(0) || excluded[to];
        if (from != address(0) && exFrom) excludedSupply -= value;
        if (to != address(0) && exTo) excludedSupply += value;
        uint256 n = rewardAssets.length;
        for (uint256 i; i < n; i++) {
            address a = rewardAssets[i];
            uint256 m = perShare[a] * value;
            if (!exFrom) _corr[a][from] += int256(m);
            if (!exTo) _corr[a][to] -= int256(m);
        }
    }
}
